# The audited sources now live in this repository (see domains/README.md).  Point
# QPT128_SOURCES at the repository root, or leave it unset and the tree is found by
# walking up from this file.  Every name passed to _load() is a file in that tree.
QPT128_SOURCES = os.environ.get('QPT128_SOURCES') or _find_repo_root()


def _find_repo_root():
    p = pathlib.Path(__file__).resolve()
    for parent in [p.parent, *p.parents]:
        if (parent / 'domains').is_dir():
            return str(parent)
    raise SystemExit('repository root not found; set QPT128_SOURCES')


def _resolve(filename):
    if os.path.isabs(filename) and os.path.exists(filename):
        return filename
    for hit in sorted(pathlib.Path(QPT128_SOURCES).glob('domains/*/*/' + filename)) + \n               sorted(pathlib.Path(QPT128_SOURCES).glob('domains/*/*/*/' + filename)):
        return str(hit)
    raise FileNotFoundError(filename)


def _load(name, filename):
    spec = importlib.util.spec_from_file_location(name, _resolve(filename))

for name in ("paired_reference.py", "make_fixture.py"):
    shutil.copy2(source / name, output / name)
for name in ("run_native.py", "verify_public.py", "check_public_mutations.py"):
    shutil.copy2(source.parent / "history/v1.27b" / name, output / name)
